/**
 * DOCB-8738: which PO-Match rule version cards may be deleted.
 *
 * Extracted from `Rules.vue` so the rule can be locked behaviour-tested in
 * isolation — the same reason `computeQuickSearchSlots.ts` was lifted out of
 * `quick-search.vue`. The version drawer template and `deleteVersion()` must
 * both go through this one predicate; two copies of the rule is how the bug
 * got in.
 *
 * ## The bug
 *
 * The drawer used to gate its Delete menu item on `item.is_draft`, while the
 * backend gates the actual DELETE on `is_approved`:
 *
 *   DocBits_API routers/document_type_attributes/router.py
 *     @router.delete("/value/by-id/{value_id}")
 *       if value.is_approved:
 *           raise FellowHTTPException(403, "Approved values cannot be deleted.")
 *
 * `is_draft`, `is_approved` and `is_active` are three independent columns, so
 * the two predicates drift apart in both directions:
 *
 *   1. `is_draft=false, is_approved=false` — reachable because the create
 *      endpoint writes all three flags verbatim from the request, and
 *      `PATCH /value/{id}/toggle-active?is_active=false` ("Deactivate") clears
 *      only `is_active`. Such a card renders the badge "Draft" (getStatus
 *      falls through to its else branch) but showed NO Delete item, even
 *      though the backend would have deleted it. Two cards both badged
 *      "Draft", only one deletable — exactly what the ticket reports.
 *
 *   2. `is_draft=true, is_approved=true` — the stale-local-state case.
 *      `approveVersion()` used to patch only `is_approved = true` on the local
 *      object while the server also set `is_draft = false`. The Delete item
 *      stayed visible, the click passed the stale local guard, and the request
 *      came back 403.
 *
 * ## The rule
 *
 * Mirror the backend (`!is_approved`) and additionally refuse the version that
 * is currently live. Activation always sets `is_approved = true`, so
 * `is_active` normally implies non-deletable anyway; the extra clause only
 * covers a value created directly with `is_active=true, is_approved=false`,
 * where deleting the rule set the org is matching against would be a
 * foot-gun. This keeps the predicate a strict subset of what the backend
 * accepts: the UI never offers a Delete that the API answers with 403.
 *
 * Note `is_draft` deliberately plays no part. It drives *editability*
 * (`isFormReadOnly`), which is a different question from deletability.
 */

export interface RuleVersionFlags {
  is_draft?: boolean | null;
  is_active?: boolean | null;
  is_approved?: boolean | null;
}

/**
 * True when the version card may offer — and perform — a delete.
 *
 * Written with `!== true` rather than `!` so that a missing or null flag (an
 * older backend response, or a locally-constructed entry) is treated as "not
 * approved / not active" and stays deletable, matching how the backend reads
 * its NOT NULL-defaulted booleans.
 */
export function canDeleteVersion(
  item: RuleVersionFlags | null | undefined,
): boolean {
  if (!item) return false;
  return item.is_approved !== true && item.is_active !== true;
}
