        { name: 'allow_tolerance', label: this.$t('allow_tolerance'), field: 'allow_tolerance', align: 'left' },
        { name: 'action', label: this.$t('action'), field: 'action', align: 'left', style: 'width: 80px', headerStyle: 'width: 80px' }
      ] as any[];
    },
    sortRulesByPriority() {
      // Sort rules by priority
      this.rules.sort((a: any, b: any) => a.priority - b.priority);

      // Update selected rule index if a rule is selected
      if (this.selectedRule) {
        const selectedRuleName = this.selectedRule.name;
        this.selectRuleIndex = this.rules.findIndex((r: any) => r.name === selectedRuleName);
      }
    },
    loadDefaultRule() {
      // Extract rules
      this.rules = this.poConfiguration?.rules || [];

      // Ensure all rules have proper default values for toggle properties
       
      this.rules = this.rules.map((rule: any) => ({
        ...rule,
        is_active: rule.is_active ?? true,
        auto_match: rule.auto_match ?? false,
        manual_match: rule.manual_match ?? false,
        allow_packages: rule.allow_packages ?? false,
        normalize_unit_before_match: rule.normalize_unit_before_match ?? false,
        // Ensure columns_to_match rows also have defaults
         
        columns_to_match: (rule.columns_to_match || []).map((col: any) => ({
          ...col,
          ignore_for_manual_match: col.ignore_for_manual_match ?? false,
          allow_tolerance: col.allow_tolerance ?? false
        }))
      }));

      // Sort rules by priority
      this.sortRulesByPriority();

      if(!this.rules || this.rules.length == 0) {
        this.selectedRule = null;
        return;
      }
      // Default selection
      this.selectedRule = JSON.parse(JSON.stringify(this.rules[0]));
      this.selectRuleIndex = 0;
    },

    addRule() {
      if (this.isFormReadOnly) {
        notify.error(this.$t('cannot_add_rules_to_published_version'));
        return;
      }

      const newRule = {
        name: `Rule #${this.rules.length + 1}`,
        description: `Rule description #${this.rules.length + 1}`,
        is_active: true,
        priority: this.rules.length + 1,
        auto_match: true,
        manual_match: true,
        rule_type: 'single_match',
        activation_conditions: [],
        normalize_unit_before_match: true,
        allow_packages: true,
        allowed_packages: [10,20,100,1000],
        columns_to_match: []
      };

      this.rules.push(newRule);
      this.selectedRule = JSON.parse(JSON.stringify(newRule));
      this.selectRuleIndex = this.rules.length - 1;
    },
    selectRule(rule: any, index: number) {
      this.selectedRule = JSON.parse(JSON.stringify(rule));
      this.selectRuleIndex = index;
    },
    saveSelectedRule() {
      if (!this.selectedRule || this.selectRuleIndex === null) {
        notify.error('No rule selected to save');
        return;
      }

      // Update the rule in the rules array at the current index
      this.rules[this.selectRuleIndex] = JSON.parse(JSON.stringify(this.selectedRule));

      // Sort rules by priority to update table rendering
      this.sortRulesByPriority();

      notify.success('Rule saved successfully');
    },
    deleteRule(index: number) {
      // Remove the rule from the array
      this.rules.splice(index, 1);

      // If the deleted rule was selected, clear selection or select another rule
      if (this.selectRuleIndex === index) {
        if (this.rules.length > 0) {
          // Select the previous rule or the first one
          const newIndex = index > 0 ? index - 1 : 0;
          this.selectedRule = JSON.parse(JSON.stringify(this.rules[newIndex]));
          this.selectRuleIndex = newIndex;
        } else {
          // No rules left
          this.selectedRule = null;
          this.selectRuleIndex = null;
        }
      } else if (this.selectRuleIndex !== null && this.selectRuleIndex > index) {
        // Adjust the selected index if it's after the deleted rule
        this.selectRuleIndex--;
      }
    },
    duplicateRule(index: number) {

      // Deep copy the rule at the given index
      const ruleToDuplicate = JSON.parse(JSON.stringify(this.rules[index]));

      // Update name and description to indicate it's a copy
      ruleToDuplicate.name = `${ruleToDuplicate.name as string} (Copy)`;
      ruleToDuplicate.description = `${ruleToDuplicate.description as string} (Copy)`;
      ruleToDuplicate.priority = this.rules.length + 1;

      // Insert the duplicated rule right after the original
      this.rules.splice(index + 1, 0, ruleToDuplicate);

      // Select the newly duplicated rule
      this.selectedRule = JSON.parse(JSON.stringify(ruleToDuplicate));
      this.selectRuleIndex = index + 1;

      notify.success(this.$t('Rule saved successfully'));
    },
    openMatchRowForm() {
      this.showMatchRowForm = true
      this.editingMatchRowIndex = null
      this.resetMatchRowObject()
    },
    closeMatchRowForm() {
      this.showMatchRowForm = false
      this.editingMatchRowIndex = null
      this.resetMatchRowObject()
    },
    editColumnsToMatchRow(row: any, index: number) {
      if (!this.selectedRule) return

      this.editingMatchRowIndex = index
      this.matchRowObject = {
        ...row,
        ignore_for_manual_match: row.ignore_for_manual_match ?? false,
        allow_tolerance: row.allow_tolerance ?? false
      }
      this.showMatchRowForm = true;
    },
    saveColumnsToMatchRow() {
      if (!this.selectedRule) return
      if (!Array.isArray(this.selectedRule.columns_to_match)) {
        this.selectedRule.columns_to_match = []
      }

      if (this.editingMatchRowIndex !== null) {
        // Update existing row
        this.selectedRule.columns_to_match[this.editingMatchRowIndex] = { ...this.matchRowObject }
      } else {
        // Add new row
        this.selectedRule.columns_to_match.push({ ...this.matchRowObject })
      }

      this.closeMatchRowForm()
    },
    deleteColumnsToMatchRow(index: number) {
      if (!this.selectedRule) return
      if (!Array.isArray(this.selectedRule.columns_to_match)) return

      // Remove the row from the array
      this.selectedRule.columns_to_match.splice(index, 1);

      // If we were editing the deleted row, close the form
      if (this.editingMatchRowIndex === index) {
        this.closeMatchRowForm();
      } else if (this.editingMatchRowIndex !== null && this.editingMatchRowIndex > index) {
        // Adjust the editing index if it's after the deleted row
        this.editingMatchRowIndex--;
      }
    },
    duplicateColumnsToMatchRow(index: number) {
      if (!this.selectedRule) return
      if (!Array.isArray(this.selectedRule.columns_to_match)) return

      // Deep copy the row at the given index
      const rowToDuplicate = JSON.parse(JSON.stringify(this.selectedRule.columns_to_match[index]));

      // Insert the duplicated row right after the original
      this.selectedRule.columns_to_match.splice(index + 1, 0, rowToDuplicate);

      // Update the editing index if needed
      if (this.editingMatchRowIndex !== null && this.editingMatchRowIndex >= index + 1) {
        this.editingMatchRowIndex++;
      }

      notify.success(this.$t('Saved successfully'));
    },
    resetMatchRowObject() {
      this.matchRowObject = {
        comparison_type: 'string',
        po_column: '',
        extracted_table_column: '',
        ignore_for_manual_match: false,
        allow_tolerance: false
      }
    },
    preparePoColumnMatchTypeList() {
      // values needs to be the exect keys of po table columns
      this.po_quantity_type_list = [
        {
          label: this.$t('quantity'),
          value: 'quantity'
        },
        {
          label: this.$t('received_quantity'),
          value: 'received_quantity'
        },
        {
          label: this.$t('received_delivery_open_quantity'),
          value: 'invoice_open_quantity'
        }
      ];
    },
    prepareRulesConfigurations() {

      // Update the selected rule in the rules array before saving
      if (this.selectedRule && this.selectRuleIndex !== null) {
        this.rules[this.selectRuleIndex] = JSON.parse(JSON.stringify(this.selectedRule));
      }

      // Update the configuration with the latest rules
      this.poConfiguration.rules = this.rules;

      // Convert configuration to TOML string
      return stringifyToml(this.poConfiguration);
    },
    async saveConfigurations() {
      try {
        // Convert configuration to TOML string
        const tomlString = this.prepareRulesConfigurations();

        // If currentVersionId exists, update existing version using PATCH API
        if (!this.currentVersionId) {
          return
        }
        const updatePayload = { value: tomlString };

        const response = await documentTypeApiService.updateDocumentTypeAttributeValue( this.currentVersionId, updatePayload );

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        // Update the existing version in the list
        const versionIndex = this.versionList.findIndex(v => v.id === this.currentVersionId);
        if (versionIndex !== -1) {
          this.versionList[versionIndex] = response;
        }

        notify.success(this.$t('MSG_SAVE'));

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
    async getVersionList() {

      try {
        const params = {
          doc_type_key: this.doc_type
        };

        const response = await documentTypeApiService.getAllPurchaseOrderRulesRevisions(params);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        this.versionList = response;

        if(!this.versionList || this.versionList.length == 0) {
          return;
        }

        // Find active version or fall back to first version
        const activeVersion = this.versionList.find(item => item.is_active === true);
        const selectedVersion = activeVersion || this.versionList[0];

        if (selectedVersion && selectedVersion.value) {
          // Parse the TOML value from the selected version
          this.poConfiguration = TOML.parse(selectedVersion.value);

          // Check if the loaded version is draft (only draft versions are editable)
          this.isFormReadOnly = selectedVersion.is_draft !== true;
          this.currentVersionId = selectedVersion.id;
        }

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
    toggleSidebar() {
      this.sidebarOpen = !this.sidebarOpen;
    },
    closeSidebar() {
      this.sidebarOpen = false;
    },
    // DOCB-8738: exposed as a method so the version drawer template and
    // deleteVersion() share one deletability rule. Logic lives in
    // ./versionCapabilities.ts, where it is unit-tested against the backend
    // contract.
    canDeleteVersion(item: any) {
      return canDeleteVersion(item);
    },
    getStatus(item: any) {
      
      if(item.is_active) {
        return this.$t('activate');
      } else if(item.is_approved) {
        return this.$t('approved');
      } else {
        return this.$t('draft');
      }

    },
    getStatusClass(item: any) {
      
      if(item.is_active) {
        return 'positive';
      } else if(item.is_approved) {
        return 'grey-6';
      } else {
        return 'warning';
      }

    },
    loadVersion(version: any) {
      try {
        if (!version || !version.value) {
          notify.error('Invalid version data');
          return;
        }

        // Parse the TOML value from the selected version
        this.poConfiguration = TOML.parse(version.value);

        // Update the read-only state based on version status (only draft versions are editable)
        this.isFormReadOnly = version.is_draft !== true;
        this.currentVersionId = version.id;

        // Reload the rules from the selected version
        this.loadDefaultRule();

        const statusMsg = this.isFormReadOnly
          ? 'Loaded published version (read-only)'
          : 'Loaded draft version (editable)';
        notify.success(statusMsg);

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async approveVersion(value: any) {
      try {
        if (!value.id) {
          notify.error('value ID is required');
          return;
        }

        const response = await documentTypeApiService.approveDocumentTypeAttributeValue(value.id);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        // DOCB-8738: the server also clears is_draft when it approves, so
        // patching only is_approved locally left the card in a state that
        // exists nowhere in the database — the Delete item stayed visible and
        // the click came back 403. Take the flags from the response instead of
        // hand-maintaining a subset. Merged rather than replaced so the
        // display-only fields the response omits (created_by / created_on)
        // survive, and deliberately NOT a getVersionList() refresh: that would
        // reload poConfiguration and discard unsaved edits to another draft.
        const versionIndex = this.versionList.findIndex(v => v.id === value.id);
        if (versionIndex !== -1) {
          this.versionList[versionIndex] = {
            ...this.versionList[versionIndex],
            ...response,
          };
        }
        notify.success('Version approved successfully');

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async toggleVersionActive(value: any) {
      try {
        if (!value.id) {
          notify.error('value ID is required');
          return;
        }

        // Toggle the is_active status
        const newActiveStatus = !value.is_active;

        const response = await documentTypeApiService.toggleActiveDocumentTypeAttributeValue(value.id, newActiveStatus);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        // Update the value object in the list
        notify.success(`Version ${newActiveStatus ? 'activated' : 'deactivated'} successfully`);
        await this.getVersionList();

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async cloneAsDraft(value: any) {
      try {
        if (!value.id) {
          notify.error('value ID is required');
          return;
        }

        const params = {
          value_id: value.id,
        };

        const response = await documentTypeApiService.clonePurchaseOrderRulesAsDraft(params);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        // Add the cloned value to the top of the list
        this.versionList.unshift(response);

        // Load the cloned draft version
        if (response && response.value) {
          this.poConfiguration = TOML.parse(response.value);
          this.isFormReadOnly = false; // Draft version is not active
          this.currentVersionId = response.id;
          this.loadDefaultRule(); // Reload the rules from the cloned version
        }

        notify.success('Version cloned as draft successfully. You can now edit the configuration.');

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async deleteVersion(value: any) {
      try {
        if (!value.id) {
          notify.error('value ID is required');
          return;
        }

        // DOCB-8738: same predicate the template uses for the menu item, so
        // the affordance and the guard can never drift apart again. It mirrors
        // the backend rule (403 "Approved values cannot be deleted."); the old
        // `!value.is_draft` check was a different, unrelated flag.
        if (!canDeleteVersion(value)) {
          notify.error('Approved or active versions cannot be deleted');
          return;
        }

        const response = await documentTypeApiService.deletePurchaseOrderRule(value.id);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        // Remove the deleted version from the list
        const versionIndex = this.versionList.findIndex(v => v.id === value.id);
        if (versionIndex !== -1) {
          this.versionList.splice(versionIndex, 1);
        }

        // If the deleted version was the current one, load another version
        if (this.currentVersionId === value.id) {
          if (this.versionList.length > 0) {
            this.loadVersion(this.versionList[0]);
          } else {
            this.poConfiguration = {};
            this.currentVersionId = null;
            this.loadDefaultRule();
          }
        }

        notify.success('Version deleted successfully');

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async fetchExtractedTableColumns() {
      try {

        const response = await documentTypeApiService.getTableColumns(this.doc_type);

        if (response.data && response.data.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        this.extractedTableColumnOptions = [];

        for (let [tbl_name, tbl] of Object.entries(response.data)) {
          const table = tbl as dynamicObj;
          for (let [index, col] of Object.entries(table)) {
            const row = col as dynamicObj;
            let newRow: dynamicObj = { ...row };
            // newRow['table_name'] = tbl_name;
            this.extractedTableColumnOptions.push({ label: this.getLabelToDisplay(newRow), value: newRow.column_name });
          }
        }

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
    async resetToDefault() {
      try {
        if (!this.doc_type) {
          notify.error('Document type is required');
          return;
        }

        const response = await documentTypeApiService.resetPurchaseOrderRulesToDefault(this.doc_type);

        if (response && response.hasOwnProperty('success') && response.success === false) {
          throw response;
        }

        notify.success('Purchase order rules reset to default successfully');

        // Reload the version list to reflect the changes
        await this.getVersionList();

      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async preparePOTableColumns() {
      this.poColumnOptions = [];
      await this.getPOColumns(this.doc_type);

      for (const [column_name, col] of Object.entries(this.poTableColumns)) {
        const column = col as any;
        if (column && column.translation_key && column.name) {
          this.poColumnOptions.push({
            label: this.$t(column.translation_key),
            value: column.name,
          });
        }
      }

    },
    prepareRuleTypeOptions() {
      this.ruleTypeOptions = [
        { label: this.$t('single_match'), value: 'single_match' },
        { label: this.$t('multi_match'), value: 'multi_match' },
        { label: this.$t('match_on_total'), value: 'match_on_total' },
      ] as any[];
    },
    getComparisonTypeIcon(comparisonType: string) {
      const iconMap: Record<string, string> = {
        'string': 'text_fields',
        'numeric': 'tag',
        'date': 'event',
        'item_identifier': 'inventory_2'
      };
      return iconMap[comparisonType] || 'help_outline';
    },
    getComparisonTypeLabel(comparisonType: string) {
      const labelMap: Record<string, string> = {
        'string': this.$t('string'),
        'numeric': this.$t('numeric'),
        'date': this.$t('date'),
        'item_identifier': this.$t('item_identifier')
      };
      return labelMap[comparisonType] || comparisonType;
    },
    getMatchQuantityLabel(value: string) {
      const option = this.po_quantity_type_list.find((item: any) => item.value === value);
      return option ? String(option.label) : value;
    },
    onDragStart(event: DragEvent, index: number) {
      if (this.isFormReadOnly) {
        event.preventDefault();
        return;
      }
      this.draggedRuleIndex = index;
      if (event.dataTransfer) {
        event.dataTransfer.effectAllowed = 'move';
      }
    },
    onDragOver(event: DragEvent, index: number) {
      if (this.isFormReadOnly) return;
      this.dragOverIndex = index;
    },
    onDragEnd() {
      this.draggedRuleIndex = null;
      this.dragOverIndex = null;
    },
    onDrop(event: DragEvent, dropIndex: number) {
      event.preventDefault();
      if (this.isFormReadOnly || this.draggedRuleIndex === null) return;

      const dragIndex = this.draggedRuleIndex;

      // Move the rule in the array
      const draggedRule = this.rules[dragIndex];
      this.rules.splice(dragIndex, 1);
      this.rules.splice(dropIndex, 0, draggedRule);

      // Update priorities based on new order
      this.rules.forEach((rule: any, index: number) => {
        rule.priority = index + 1;
      });

      // Update selected rule index if needed
      if (this.selectRuleIndex === dragIndex) {
        this.selectRuleIndex = dropIndex;
        this.selectedRule = JSON.parse(JSON.stringify(this.rules[dropIndex]));
      } else if (dragIndex < this.selectRuleIndex! && dropIndex >= this.selectRuleIndex!) {
        this.selectRuleIndex!--;
      } else if (dragIndex > this.selectRuleIndex! && dropIndex <= this.selectRuleIndex!) {
        this.selectRuleIndex!++;
      }

      this.draggedRuleIndex = null;
      this.dragOverIndex = null;
    }

  },
  setup () {

    const po_match_store = usePoMatchStore();
    const { table_columns: poTableColumns } = storeToRefs(po_match_store);
    const { getPOColumns } = po_match_store;

    return {
      getPOColumns,
      poTableColumns,
      poConfiguration: ref({} as any),
      po_quantity_type_list: ref([] as any),

    }
  },
})
</script>

